import{R as e,S as t,x as n}from"./vue-Bp4HY3mp.js";import{n as r}from"./app-C11vx5L5.js";var i=JSON.parse(`{"path":"/english/vocabulary/animal-protection/researchers-and-groups/","title":"CH3.1 研究者与动物类群 | 英语","lang":"zh-CN","frontmatter":{"title":"CH3.1 研究者与动物类群","createTime":"2026-11-20T10:00:00.000Z","permalink":"/english/vocabulary/animal-protection/researchers-and-groups/"},"readingTime":{"minutes":36.49,"words":10947},"git":{"createdTime":1795161551000},"filePathRelative":"english/vocabulary/animal-protection/1.researchers-and-groups.md","headers":[],"bulletin":false}`),a={name:`1.researchers-and-groups.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<div class="vocab-card"><h2 id="biologist" tabindex="-1"><a class="header-anchor" href="#biologist"><span>Biologist</span></a></h2><p class="vc-meta"><strong>/baɪˈɒlədʒɪst/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>生物学家；研究生命现象与生物体的学者</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a marine biologist</td><td>海洋生物学家</td></tr><tr><td>a conservation biologist</td><td>保护生物学家</td></tr><tr><td>work as a biologist</td><td>从事生物学研究</td></tr><tr><td>a team of biologists</td><td>一支生物学家团队</td></tr><tr><td>biologists studying ...</td><td>研究……的生物学家</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares the number of biologists employed in four research fields between 2005 and 2020.</p><blockquote><p>该图比较了 2005 至 2020 年间四个研究领域雇佣的生物学家数量。</p></blockquote><p><strong>Writing Task 2</strong> Biologists warn that the loss of a single keystone species can unravel an entire ecosystem.</p><blockquote><p>生物学家警告，失去一个关键物种就可能瓦解整个生态系统。</p></blockquote><p><strong>Speaking</strong> My cousin is a biologist — she spends half the year counting fish on a coral reef.</p><blockquote><p>我表姐是生物学家，她一年有半年在珊瑚礁上数鱼。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>life scientist</td><td>生命科学家</td><td>正式、偏政策文本，涵盖面比 biologist 更宽</td></tr><tr><td>naturalist</td><td>博物学者</td><td>强调野外观察与记录，不一定是科班研究者</td></tr><tr><td>ecologist</td><td>生态学家</td><td>只研究生物与环境的关系，范围更窄</td></tr><tr><td>researcher</td><td>研究者</td><td>通用词，不限定学科</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> bio-（希腊语 <em>bios</em>，生命）+ -logy（学科）+ -ist（从事者）</li><li><strong>Family:</strong> biology 生物学 / biological 生物的 / biodiversity 生物多样性 / antibiotic 抗生素</li><li><strong>Memory Tip:</strong> -ist 是&quot;人&quot;，-logy 是&quot;学问&quot;。先记 biology，再把结尾换成 -ist 就是&quot;搞这门学问的人&quot;，一整串学科都能这么造。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>学科是 biology，研究者才是 biologist：<s>He studies biologist.</s> ✘</li><li>重音在第二音节 /baɪˈɒlədʒɪst/，不在第一音节。</li><li>指某一类研究者时用复数泛指：Biologists <strong>have</strong> long argued ... ✔</li></ul></div><div class="vocab-card"><h2 id="zoologist" tabindex="-1"><a class="header-anchor" href="#zoologist"><span>Zoologist</span></a></h2><p class="vc-meta"><strong>/zəʊˈɒlədʒɪst/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>动物学家；专门研究动物分类、行为与生理的学者</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a field zoologist</td><td>野外动物学家</td></tr><tr><td>zoologists and botanists</td><td>动物学家与植物学家</td></tr><tr><td>a zoologist&#39;s observations</td><td>动物学家的观察记录</td></tr><tr><td>train as a zoologist</td><td>接受动物学专业训练</td></tr><tr><td>zoologists working in ...</td><td>在……工作的动物学家</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The table shows how many zoologists were employed by wildlife parks in each region in 2019.</p><blockquote><p>该表显示了 2019 年各地区的野生动物园雇佣了多少动物学家。</p></blockquote><p><strong>Writing Task 2</strong> Zoologists argue that captive breeding programmes are a last resort, not a substitute for protecting habitats.</p><blockquote><p>动物学家认为，圈养繁殖计划是最后手段，而非保护栖息地的替代方案。</p></blockquote><p><strong>Speaking</strong> A zoologist came to our school and brought a snake — half the class ran out of the room.</p><blockquote><p>有位动物学家来我们学校，还带了条蛇，半个班都跑出去了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>animal scientist</td><td>动物科学家</td><td>少见、偏行政表述，学术文本仍用 zoologist</td></tr><tr><td>ethologist</td><td>动物行为学家</td><td>只研究行为，不涉及分类与解剖</td></tr><tr><td>wildlife expert</td><td>野生动物专家</td><td>媒体用语，非严格学术称谓</td></tr><tr><td>biologist</td><td>生物学家</td><td>上位词，范围包含 zoologist</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> zoo-（希腊语 <em>zōion</em>，动物）+ -logy（学科）+ -ist（人）</li><li><strong>Family:</strong> zoology 动物学 / zoo 动物园 / protozoa 原生动物 / zodiac（同源&quot;动物圈&quot;）</li><li><strong>Memory Tip:</strong> zoo 不只是&quot;动物园&quot;，本义就是&quot;动物&quot;。zoology 是动物学，加上 -ist 才是人；和 biology / botanist 一起记，三个词根一网打尽。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>别和 <strong>zookeeper</strong> 混：zookeeper 是饲养员，zoologist 是研究者。</li><li>拼写是 zoo-，不是 <s>zu-</s>；结尾 -logist 不是 -logist 之外的其他变体。</li><li>说&quot;动物学&quot;用 zoology，别说 <s>zoologist</s>：She studied <strong>zoology</strong> at university. ✔</li></ul></div><div class="vocab-card"><h2 id="ecologist" tabindex="-1"><a class="header-anchor" href="#ecologist"><span>Ecologist</span></a></h2><p class="vc-meta"><strong>/iˈkɒlədʒɪst/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>生态学家；研究生物与环境的相互关系的人</li><li>（引申）环保主义者（口语中偶见，正式文本少用）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a marine ecologist</td><td>海洋生态学家</td></tr><tr><td>ecologists and conservationists</td><td>生态学家与环保人士</td></tr><tr><td>according to ecologists</td><td>据生态学家所言</td></tr><tr><td>an ecologist&#39;s survey</td><td>生态学家的调查</td></tr><tr><td>ecologists studying ...</td><td>研究……的生态学家</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The line graph shows the recovery of fish stocks recorded by ecologists in three coastal areas.</p><blockquote><p>该折线图显示了生态学家在三个沿海地区记录到的鱼类资源恢复情况。</p></blockquote><p><strong>Writing Task 2</strong> Ecologists point out that a river&#39;s health cannot be judged by water clarity alone, since invisible pollutants may persist for decades.</p><blockquote><p>生态学家指出，河流的健康不能只看水的清澈度，因为看不见的污染物可能存留数十年。</p></blockquote><p><strong>Speaking</strong> An ecologist told us that the pond behind the school supports more species than the whole housing estate.</p><blockquote><p>一位生态学家告诉我们，学校后面的池塘养的物种比整个住宅区还多。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>environmental scientist</td><td>环境科学家</td><td>偏理化监测与治理，未必研究生物</td></tr><tr><td>conservationist</td><td>自然保护者</td><td>强调保护行动，可非专业出身</td></tr><tr><td>biologist</td><td>生物学家</td><td>上位词，不突出&quot;与环境的关系&quot;</td></tr><tr><td>naturalist</td><td>博物学者</td><td>侧重物种记录，理论分析较少</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> eco-（希腊语 <em>oikos</em>，家、住所）+ -logy（学科）</li><li><strong>Family:</strong> ecology 生态学 / ecosystem 生态系统 / economy 经济（同源&quot;持家&quot;）/ ecotourism 生态旅游</li><li><strong>Memory Tip:</strong> oikos 是&quot;家&quot;。生态学就是研究&quot;大自然的家务事&quot;——谁住在哪、吃什么、和谁抢地方；同源的 economy 是&quot;人类持家&quot;，两个词一起记特别省力。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>ecology 是&quot;生态/生态学&quot;，ecologist 才是人；&quot;环境&quot;用 environment，不说 <s>ecology</s>。</li><li>重音在第二音节 /iˈkɒlədʒɪst/；首音节弱读成 /ɪ/ 更自然。</li><li>别与 <strong>environmentalist</strong> 混：后者指主张环保的行动者，不一定是研究者。</li></ul></div><div class="vocab-card"><h2 id="botanist" tabindex="-1"><a class="header-anchor" href="#botanist"><span>Botanist</span></a></h2><p class="vc-meta"><strong>/ˈbɒtənɪst/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>植物学家；研究植物分类、结构与生长的学者</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a keen botanist</td><td>热衷植物研究的人</td></tr><tr><td>botanists and zoologists</td><td>植物学家与动物学家</td></tr><tr><td>a botanist&#39;s collection</td><td>植物学家的标本集</td></tr><tr><td>classified by botanists</td><td>由植物学家分类</td></tr><tr><td>an amateur botanist</td><td>业余植物爱好者</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The bar chart shows the number of new plant species identified by botanists in each decade.</p><blockquote><p>该柱状图显示了每个十年植物学家新鉴定的植物物种数量。</p></blockquote><p><strong>Writing Task 2</strong> Botanists have long warned that replacing native vegetation with a single cash crop leaves farmland far more vulnerable to disease.</p><blockquote><p>植物学家早已警告，用单一经济作物取代原生植被，会让农田更容易遭受病害。</p></blockquote><p><strong>Speaking</strong> My grandmother is an amateur botanist — she can name every weed in the garden.</p><blockquote><p>我奶奶是业余植物爱好者，园子里每棵草她都叫得出名字。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>plant scientist</td><td>植物科学家</td><td>现代行政用语，传统学界仍用 botanist</td></tr><tr><td>horticulturist</td><td>园艺学家</td><td>侧重栽培与育种，不研究野生分类</td></tr><tr><td>naturalist</td><td>博物学者</td><td>动植物兼涉，专业性较弱</td></tr><tr><td>biologist</td><td>生物学家</td><td>上位词，不限定研究对象</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> botane（希腊语&quot;牧草、植物&quot;）→ botany 植物学</li><li><strong>Family:</strong> botany 植物学 / botanical 植物的 / botanical garden 植物园 / botanise 采集植物标本</li><li><strong>Memory Tip:</strong> 逛植物园看到 <strong>botanical garden</strong> 的牌子，就等于看到了 botanist 的词根：botan- 是&quot;植物&quot;。同一词根在生活里出现频率极高，比死记拼写有效。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>学科是 botany，人是 botanist；&quot;植物园的&quot;用 <strong>botanical</strong>，不是 <s>botanic</s>（后者多见于机构旧名）。</li><li>别和 <strong>biologist</strong> 混用：botanist 只研究植物。</li><li>拼写中间是 -tan-，不是 <s>-ton-</s>。</li></ul></div><div class="vocab-card"><h2 id="creature" tabindex="-1"><a class="header-anchor" href="#creature"><span>Creature</span></a></h2><p class="vc-meta"><strong>/ˈkriːtʃə(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>生物；动物（常带感情色彩，指&quot;小家伙&quot;&quot;活物&quot;）</li><li>（虚构的）怪物、造物</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a living creature</td><td>一个活物</td></tr><tr><td>a tiny creature</td><td>微小生物</td></tr><tr><td>a sea creature</td><td>海洋生物</td></tr><tr><td>a strange creature</td><td>奇怪的生物</td></tr><tr><td>every creature on earth</td><td>地球上的每一个生灵</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how a single-celled creature responds to changes in light intensity.</p><blockquote><p>该示意图展示了一个单细胞生物如何对光照强度的变化作出反应。</p></blockquote><p><strong>Writing Task 2</strong> Every creature in the food chain, however small, plays a role that is difficult to replace once lost.</p><blockquote><p>食物链上的每一个生灵，无论多小，都承担着一旦失去便难以替代的角色。</p></blockquote><p><strong>Speaking</strong> We found this weird creature under a rock — it looked like a shrimp with too many legs.</p><blockquote><p>我们在石头底下发现一个怪东西，长得像长了太多腿的虾。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>animal</td><td>动物</td><td>中性、科学，不含感情色彩</td></tr><tr><td>being</td><td>生命体</td><td>抽象、书面，常用于哲学讨论</td></tr><tr><td>organism</td><td>生物体</td><td>学术词，含微生物与植物</td></tr><tr><td>beast</td><td>野兽</td><td>体型大、有威胁感，文学色彩强</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>creare</em>（创造）→ creature 即&quot;被造之物&quot;</li><li><strong>Family:</strong> create 创造 / creation 创造 / creative 有创造力的 / creator 创造者</li><li><strong>Memory Tip:</strong> creature 的词根就是&quot;创造&quot;——一切&quot;被造出来的活物&quot;。记住 create 就顺带记住了它；科幻片里的&quot;造物&quot;也用它。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>creature 可数，泛指一类时用复数：<s>a creature</s> 单独泛指不自然，应说 creatures。</li><li>感情色彩比 animal 强，学术写作描述物种时优先用 animal / organism。</li><li>拼写是 crea-，不是 <s>cere-</s>；注意 -ture 结尾读 /tʃə(r)/。</li></ul></div><div class="vocab-card"><h2 id="wildlife" tabindex="-1"><a class="header-anchor" href="#wildlife"><span>Wildlife</span></a></h2><p class="vc-meta"><strong>/ˈwaɪldlaɪf/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>野生动物；野生生物（总称，不可数）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>protect wildlife</td><td>保护野生动物</td></tr><tr><td>wildlife conservation</td><td>野生动物保护</td></tr><tr><td>a wildlife reserve</td><td>野生动物保护区</td></tr><tr><td>wildlife habitat</td><td>野生动物栖息地</td></tr><tr><td>damage to wildlife</td><td>对野生动物的伤害</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows public spending on wildlife protection in five countries in 2022.</p><blockquote><p>该图显示了 2022 年五个国家在野生动物保护上的公共支出。</p></blockquote><p><strong>Writing Task 2</strong> Roads cut through forests and fragment habitats, forcing wildlife into contact with traffic, poachers and human settlements.</p><blockquote><p>公路穿过森林、割裂栖息地，迫使野生动物与车流、盗猎者和人类聚居区接触。</p></blockquote><p><strong>Speaking</strong> There&#39;s a wildlife park an hour from my hometown — you can see deer wandering right up to the car.</p><blockquote><p>我老家一小时车程外有个野生动物园，鹿会一直走到车边。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>wild animals</td><td>野生动物</td><td>可数表达，需具体或泛指复数，不如 wildlife 简洁</td></tr><tr><td>fauna</td><td>动物群</td><td>学术词，常与 flora 并列，不强调&quot;野生&quot;保护语境</td></tr><tr><td>nature</td><td>自然</td><td>范围最大，含山水草木，不专指动物</td></tr><tr><td>biodiversity</td><td>生物多样性</td><td>抽象概念，指多样性本身而非个体</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> wild（野生的）+ life（生命）→ 合成词</li><li><strong>Family:</strong> wildlife 野生动物 / wildness 荒野 / wildfowl 野禽 / lifelike 逼真的</li><li><strong>Memory Tip:</strong> 英语喜欢&quot;形容词 + life&quot;造词：wildlife 野生动物、birdlife 鸟类、plantlife 植物。掌握这个模板，遇到生词也能猜。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：<s>wildlifes</s> ✘；说&quot;多种野生动物&quot;用 <strong>a variety of wildlife</strong>。</li><li>作定语时不加 -s：wildlife <strong>protection</strong> ✔ / <s>wildlives protection</s> ✘</li><li>别与 <strong>wild life</strong>（放荡生活）混淆，中间没有空格。</li></ul></div><div class="vocab-card"><h2 id="fauna" tabindex="-1"><a class="header-anchor" href="#fauna"><span>Fauna</span></a></h2><p class="vc-meta"><strong>/ˈfɔːnə/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>（某地区或某时期的）动物群；动物区系</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the local fauna</td><td>当地动物群</td></tr><tr><td>flora and fauna</td><td>动植物</td></tr><tr><td>marine fauna</td><td>海洋动物群</td></tr><tr><td>a rich fauna</td><td>丰富的动物区系</td></tr><tr><td>native fauna</td><td>本土动物</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows how the island&#39;s fauna changed after the wetland was drained.</p><blockquote><p>该地图显示了湿地被排干后岛上动物群的变化。</p></blockquote><p><strong>Writing Task 2</strong> Introduced species often outcompete native fauna because local predators have no defence against them.</p><blockquote><p>外来物种常常挤占本土动物的生存空间，因为本地捕食者对它们毫无防备。</p></blockquote><p><strong>Speaking</strong> The guide kept saying &quot;flora and fauna&quot; and I honestly just wanted to see the monkeys.</p><blockquote><p>导游一直说&quot;动植物&quot;，说实话我只想看猴子。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>animal life</td><td>动物生命</td><td>通俗表达，正式文本少用</td></tr><tr><td>wildlife</td><td>野生动物</td><td>强调&quot;野生&quot;与保护语境，不限于特定地区</td></tr><tr><td>animals</td><td>动物</td><td>最通用，缺乏&quot;区系&quot;的学术含义</td></tr><tr><td>biota</td><td>生物区系</td><td>动植物统称，比 fauna 更专业</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>Fauna</em>，罗马神话中的畜牧女神</li><li><strong>Family:</strong> flora 植物群 / faunal 动物区系的 / Faunus 牧神</li><li><strong>Memory Tip:</strong> fauna 是女神名，管畜牧；flora 是花神。两位神一管动物一管植物，&quot;flora and fauna&quot; 就是&quot;花神与牧神&quot;，画面一挂就忘不掉。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>通常带定冠词或限定语：the fauna <strong>of</strong> the region ✔；泛指时少用复数 <s>faunas</s>（学术可用）。</li><li>别写成 <s>fawna</s>；-au- 是固定拼写。</li><li>fauna 只指动物，说&quot;动植物&quot;必须 <strong>flora and fauna</strong> 成对出现。</li></ul></div><div class="vocab-card"><h2 id="flora" tabindex="-1"><a class="header-anchor" href="#flora"><span>Flora</span></a></h2><p class="vc-meta"><strong>/ˈflɔːrə/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>（某地区或某时期的）植物群；植物区系</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the native flora</td><td>本土植物群</td></tr><tr><td>flora and fauna</td><td>动植物</td></tr><tr><td>alpine flora</td><td>高山植物区系</td></tr><tr><td>a diverse flora</td><td>多样的植物区系</td></tr><tr><td>gut flora</td><td>肠道菌群</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The table compares the flora of the two valleys before and after the fire.</p><blockquote><p>该表比较了火灾前后两个山谷的植物群。</p></blockquote><p><strong>Writing Task 2</strong> Tourism brings income, but trampled paths and picked flowers can strip a fragile alpine flora within a few seasons.</p><blockquote><p>旅游带来收入，但被踩实的步道和被采摘的野花，几个季节就能剥去脆弱的高山植物群。</p></blockquote><p><strong>Speaking</strong> The sign says the island&#39;s flora includes over 400 species — I only recognised the cactus.</p><blockquote><p>牌子上说岛上有 400 多种植物，我只认得出仙人掌。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>vegetation</td><td>植被</td><td>强调整片覆盖的植物，不含&quot;区系&quot;分类义</td></tr><tr><td>plant life</td><td>植物生命</td><td>通俗表达，正式文本少用</td></tr><tr><td>plants</td><td>植物</td><td>最通用，缺乏学术色彩</td></tr><tr><td>greenery</td><td>绿植</td><td>口语，指视觉上的绿色，不指物种</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>flos / floris</em>（花）→ Flora，花神</li><li><strong>Family:</strong> flower 花（同源）/ floral 花的 / florist 花商 / flourish 繁荣（原义&quot;开花&quot;）</li><li><strong>Memory Tip:</strong> florist 是花店老板，floral 是花纹的——都指向&quot;花&quot;。Flora 就是&quot;花神掌管的全部植物&quot;，和 fauna 成对记。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>flora 通常不可数、带定冠词：the flora of the island ✔</li><li>指&quot;肠道菌群&quot;也用 flora（gut flora），这是固定搭配，不是&quot;植物&quot;。</li><li>别与 <strong>vegetation</strong> 混：flora 是&quot;有哪些种&quot;，vegetation 是&quot;长成什么样的一片&quot;。</li></ul></div><div class="vocab-card"><h2 id="species" tabindex="-1"><a class="header-anchor" href="#species"><span>Species</span></a></h2><p class="vc-meta"><strong>/ˈspiːʃiːz/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>物种（生物学分类的基本单位）</li><li>种类、类型（泛指某一类人或事物）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>endangered species</td><td>濒危物种</td></tr><tr><td>a rare species</td><td>稀有物种</td></tr><tr><td>a species of ...</td><td>一种……</td></tr><tr><td>the origin of species</td><td>物种起源</td></tr><tr><td>invasive species</td><td>入侵物种</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows the number of endangered species recorded in each region between 1990 and 2020.</p><blockquote><p>该图显示了 1990 至 2020 年间各地区记录到的濒危物种数量。</p></blockquote><p><strong>Writing Task 2</strong> Once a species falls below a critical population size, inbreeding alone can push it towards extinction.</p><blockquote><p>一旦某物种的种群数量低于临界值，仅近亲繁殖一项就足以把它推向灭绝。</p></blockquote><p><strong>Speaking</strong> There&#39;s a species of frog here that only comes out for two weeks a year — I was lucky to catch it.</p><blockquote><p>这里有种青蛙一年只出来两周，我运气好碰上了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>kind</td><td>种类</td><td>口语泛指，无生物学含义</td></tr><tr><td>type</td><td>类型</td><td>强调特征归类，不含繁殖隔离义</td></tr><tr><td>breed</td><td>品种</td><td>家养动物的人工培育品系</td></tr><tr><td>strain</td><td>品系</td><td>微生物、植物的实验品系</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>species</em>（外观、种类），源自 <em>specere</em>（看）</li><li><strong>Family:</strong> special 特别的 / specify 具体说明 / specimen 标本 / spectacle 景象</li><li><strong>Memory Tip:</strong> 词根 spec- 是&quot;看&quot;。species 本义&quot;看起来一样的一群&quot;——长得像、能互相繁殖，就是一个物种。同族的 specimen（标本）也是&quot;拿来给人看的东西&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>单复数同形：one species / two <strong>species</strong>；<s>specieses</s> ✘</li><li>修饰语用单数：a <strong>rare</strong> species ✔ / <s>a rares species</s> ✘</li><li>&quot;一种……&quot;用 <strong>a species of</strong> + 单数名词：a species of <strong>bird</strong> ✔</li></ul></div><div class="vocab-card"><h2 id="subgroup" tabindex="-1"><a class="header-anchor" href="#subgroup"><span>Subgroup</span></a></h2><p class="vc-meta"><strong>/ˈsʌbɡruːp/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>亚群；小组；从较大群体中划分出的一部分</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a distinct subgroup</td><td>一个独立的亚群</td></tr><tr><td>a subgroup of ...</td><td>……的一个分支</td></tr><tr><td>divide into subgroups</td><td>划分为若干小组</td></tr><tr><td>a small subgroup</td><td>小部分群体</td></tr><tr><td>within this subgroup</td><td>在这一亚群内部</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The pie chart breaks the mammal population down into four subgroups by size.</p><blockquote><p>该饼图按体型把哺乳动物种群分为四个亚群。</p></blockquote><p><strong>Writing Task 2</strong> Within any species there are subgroups adapted to slightly different conditions, and this variation is what allows evolution to proceed.</p><blockquote><p>任何物种内部都存在适应不同条件的亚群，正是这种差异让演化得以进行。</p></blockquote><p><strong>Speaking</strong> Our project group split into two subgroups — one did the interviews, one did the analysis.</p><blockquote><p>我们项目组分成两个小组，一组做访谈，一组做分析。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>subset</td><td>子集</td><td>数学、统计语境，纯逻辑划分</td></tr><tr><td>branch</td><td>分支</td><td>强调从主干分出，多用于家族、学科</td></tr><tr><td>category</td><td>类别</td><td>按属性归类，不含层级从属关系</td></tr><tr><td>subdivision</td><td>分部</td><td>行政区或机构用语，较少用于生物</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> sub-（在下、次级）+ group（群）</li><li><strong>Family:</strong> subspecies 亚种 / subcategory 子类别 / subtotal 小计 / subtitle 副标题</li><li><strong>Memory Tip:</strong> sub- 是&quot;下面一层&quot;的万能前缀：subgroup 亚群、subspecies 亚种、subtotal 小计。看到 sub- 就先想&quot;大东西里再切一刀&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>写作是一个词，中间不加空格或连字符：<s>sub group</s> / <s>sub-group</s> ✘</li><li>表示&quot;……的分支&quot;用 <strong>a subgroup of</strong>，不用 <s>a subgroup in</s>（后者指位置）。</li><li>生物学严格层级里&quot;亚种&quot;是 subspecies，别用 subgroup 代替。</li></ul></div><div class="vocab-card"><h2 id="mammal" tabindex="-1"><a class="header-anchor" href="#mammal"><span>Mammal</span></a></h2><p class="vc-meta"><strong>/ˈmæml/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>哺乳动物（胎生、哺乳、恒温、有毛的脊椎动物）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>marine mammals</td><td>海洋哺乳动物</td></tr><tr><td>large mammals</td><td>大型哺乳动物</td></tr><tr><td>a mammal species</td><td>一种哺乳动物</td></tr><tr><td>mammals and birds</td><td>哺乳动物与鸟类</td></tr><tr><td>small mammal populations</td><td>小型哺乳动物种群</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares the average body mass of mammals living in the three zones.</p><blockquote><p>该图比较了生活在三个区域的哺乳动物的平均体重。</p></blockquote><p><strong>Writing Task 2</strong> Large mammals need vast ranges, so a reserve fenced off from the surrounding land can never support a viable population.</p><blockquote><p>大型哺乳动物需要广阔的活动范围，因此与周边土地隔断的保护区无法维持可存续的种群。</p></blockquote><p><strong>Speaking</strong> Whales are mammals, which still surprises people — they feed their young on milk, just like us.</p><blockquote><p>鲸是哺乳动物，这点至今让人意外——它们和我们一样用乳汁喂养幼崽。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>warm-blooded animal</td><td>温血动物</td><td>描述性说法，也包含鸟类</td></tr><tr><td>vertebrate</td><td>脊椎动物</td><td>层级更高，范围更大</td></tr><tr><td>beast</td><td>野兽</td><td>文学性、带威胁感，非科学术语</td></tr><tr><td>creature</td><td>生物</td><td>泛称，不指明类群</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>mamma</em>（乳房）→ mammal 即&quot;有乳房的动物&quot;</li><li><strong>Family:</strong> mammary 乳房的 / mammalogy 哺乳动物学 / mamma 妈妈（同源儿语）</li><li><strong>Memory Tip:</strong> mamma 就是&quot;妈妈&quot;——哺乳动物最鲜明的特征就是&quot;喂奶&quot;。这个联系一旦建立，拼写的双 m 也不会漏。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写双 m：<strong>ma</strong>mmal ✔ / <s>mamal</s> ✘</li><li>鲸、海豚、蝙蝠都是 mammal，不要说 <s>sea animal</s> 就完事。</li><li>形容词是 <strong>mammalian</strong>：mammalian evolution ✔ / <s>mammal evolution</s>（可接受但不如前者正式）</li></ul></div><div class="vocab-card"><h2 id="primate" tabindex="-1"><a class="header-anchor" href="#primate"><span>Primate</span></a></h2><p class="vc-meta"><strong>/ˈpraɪmeɪt/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>灵长类动物（猴、猿、人等）</li><li>（宗教）大主教（首主教，正式用语）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>primates and humans</td><td>灵长类与人类</td></tr><tr><td>a primate species</td><td>一种灵长类动物</td></tr><tr><td>non-human primates</td><td>非人灵长类</td></tr><tr><td>primate behaviour</td><td>灵长类行为</td></tr><tr><td>primate evolution</td><td>灵长类演化</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows the decline in primate populations across three forest regions.</p><blockquote><p>该图显示了三个森林区域灵长类种群数量的下降情况。</p></blockquote><p><strong>Writing Task 2</strong> Studying primates helps researchers understand the origins of human cooperation, tool use and social learning.</p><blockquote><p>研究灵长类有助于研究者理解人类合作、工具使用与社会学习的起源。</p></blockquote><p><strong>Speaking</strong> The monkeys at the temple are primates, obviously, but they behave like absolute criminals.</p><blockquote><p>寺庙里的猴子当然是灵长类，但它们的行径完全是惯犯级别的。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>ape</td><td>猿</td><td>只指猿类，不含猴与人类</td></tr><tr><td>monkey</td><td>猴</td><td>口语常用，不含猿</td></tr><tr><td>anthropoid</td><td>类人猿</td><td>专业术语，范围窄</td></tr><tr><td>mammal</td><td>哺乳动物</td><td>上位词，范围大得多</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>primas</em>（第一流的、首领）→ primate 即&quot;居首的&quot;</li><li><strong>Family:</strong> prime 首要的 / primary 主要的 / primitive 原始的 / premier 首相</li><li><strong>Memory Tip:</strong> 词根 prim- 是&quot;第一&quot;。灵长类被认为是动物界&quot;最高等&quot;的一支，所以叫 primate；同族的 prime、primary 都是&quot;第一&quot;，一串记最省劲。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>学术语境常用复数泛指：<strong>Primates</strong> include humans. ✔</li><li>重音在首音节 /ˈpraɪmeɪt/；结尾是 -ate，不读 /-ət/（英式另有 /ˈpraɪmət/，属可接受变体）。</li><li>别与 <strong>predator</strong>（捕食者）混，两者拼写开头相近但意义无关。</li></ul></div><div class="vocab-card"><h2 id="vertebrate" tabindex="-1"><a class="header-anchor" href="#vertebrate"><span>Vertebrate</span></a></h2><p class="vc-meta"><strong>/ˈvɜːtɪbrət/</strong> · noun · 名词 / adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>脊椎动物（有脊柱的动物）</li><li>有脊椎的（形容词）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>vertebrates and invertebrates</td><td>脊椎动物与无脊椎动物</td></tr><tr><td>a vertebrate species</td><td>一种脊椎动物</td></tr><tr><td>vertebrate evolution</td><td>脊椎动物演化</td></tr><tr><td>land vertebrates</td><td>陆生脊椎动物</td></tr><tr><td>vertebrate anatomy</td><td>脊椎动物解剖</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The bar chart shows the proportion of vertebrates among all described species.</p><blockquote><p>该柱状图显示了脊椎动物在已描述物种中所占的比例。</p></blockquote><p><strong>Writing Task 2</strong> Although vertebrates attract most public attention, they make up only a tiny fraction of all animal species.</p><blockquote><p>尽管脊椎动物最受公众关注，它们只占全部动物物种的极小一部分。</p></blockquote><p><strong>Speaking</strong> In biology we had to memorise the five vertebrate groups — I still forget amphibians.</p><blockquote><p>生物课上要背五大脊椎动物类群，我现在还是忘掉两栖类。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>backboned animal</td><td>有脊柱的动物</td><td>解释性说法，非术语</td></tr><tr><td>mammal</td><td>哺乳动物</td><td>下位类别，范围小</td></tr><tr><td>creature</td><td>生物</td><td>泛称，不含分类信息</td></tr><tr><td>animal</td><td>动物</td><td>上位词，包含无脊椎动物</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>vertebra</em>（关节、脊椎），源自 <em>vertere</em>（转动）</li><li><strong>Family:</strong> vertebra 椎骨 / vertebral 脊椎的 / invertebrate 无脊椎动物 / vertical 垂直的</li><li><strong>Memory Tip:</strong> 脊椎是一节节能&quot;转&quot;的骨头，词根 vertere 就是转。加前缀 in- 变成&quot;没有脊椎&quot;，就是 invertebrate——一对反义一起记。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>与 <strong>invertebrate</strong> 是反义对，别写混。</li><li>拼写中间是 -tebr-，不是 <s>-tibr-</s>。</li><li>作名词时指动物本身，作形容词时才修饰：vertebrate <strong>animals</strong> ✔（但通常直接用名词复数 vertebrates）</li></ul></div><div class="vocab-card"><h2 id="reptile" tabindex="-1"><a class="header-anchor" href="#reptile"><span>Reptile</span></a></h2><p class="vc-meta"><strong>/ˈreptaɪl/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>爬行动物（蛇、蜥蜴、龟、鳄等）</li><li>（贬义）卑鄙的人（口语，少用）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>reptiles and amphibians</td><td>爬行动物与两栖动物</td></tr><tr><td>a reptile house</td><td>爬虫馆</td></tr><tr><td>reptile species</td><td>爬行动物物种</td></tr><tr><td>cold-blooded reptiles</td><td>冷血爬行动物</td></tr><tr><td>keep reptiles as pets</td><td>把爬行动物当宠物养</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The table lists the number of reptile species found in each habitat type.</p><blockquote><p>该表列出了各栖息地类型中发现的爬行动物物种数量。</p></blockquote><p><strong>Writing Task 2</strong> Because reptiles cannot regulate their own body temperature, even a small rise in average temperature can reshape where they are able to live.</p><blockquote><p>由于爬行动物无法自行调节体温，平均气温的小幅上升就可能重塑它们的可栖息范围。</p></blockquote><p><strong>Speaking</strong> My brother keeps reptiles — there&#39;s a lizard in the spare room that I refuse to look at.</p><blockquote><p>我哥养爬行动物，客房里有只蜥蜴，我拒绝看它。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>cold-blooded animal</td><td>冷血动物</td><td>描述性说法，也含两栖类和鱼类</td></tr><tr><td>amphibian</td><td>两栖动物</td><td>皮肤湿润、幼体水生，与 reptile 并列</td></tr><tr><td>lizard</td><td>蜥蜴</td><td>具体一种，不能泛指整类</td></tr><tr><td>creature</td><td>生物</td><td>泛称，无分类信息</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>repere</em>（爬行）→ reptile 即&quot;爬行的东西&quot;</li><li><strong>Family:</strong> creep 爬行（同源）/ reptilian 爬行动物的 / serpent 蛇（同源）</li><li><strong>Memory Tip:</strong> 词根就是&quot;爬&quot;。creep 与 reptile 同源，都是&quot;身子贴着地面挪&quot;。看到 reptile 就想起蛇贴着地面的画面，拼写也不会写成 -tyle。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>结尾是 <strong>-tile</strong> /taɪl/，不是 <s>-tyle</s>；重音在首音节。</li><li>龟、鳄、蛇都算 reptile，但青蛙算 amphibian，别混。</li><li>作定语用单数：reptile <strong>species</strong> ✔ / <s>reptiles species</s> ✘</li></ul></div><div class="vocab-card"><h2 id="amphibian" tabindex="-1"><a class="header-anchor" href="#amphibian"><span>Amphibian</span></a></h2><p class="vc-meta"><strong>/æmˈfɪbiən/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>两栖动物（蛙、蟾蜍、蝾螈等）</li><li>水陆两用的交通工具（引申，较少见）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>amphibians and reptiles</td><td>两栖动物与爬行动物</td></tr><tr><td>amphibian species</td><td>两栖动物物种</td></tr><tr><td>amphibian decline</td><td>两栖动物数量下降</td></tr><tr><td>a threatened amphibian</td><td>受威胁的两栖动物</td></tr><tr><td>amphibian habitat</td><td>两栖动物栖息地</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the number of amphibian species recorded in the wetland over four decades.</p><blockquote><p>该图显示了四十年来湿地记录到的两栖动物物种数量。</p></blockquote><p><strong>Writing Task 2</strong> Amphibians are regarded as an early warning system for environmental health because their permeable skin absorbs pollutants directly.</p><blockquote><p>两栖动物被视为环境健康的预警系统，因为它们通透的皮肤会直接吸收污染物。</p></blockquote><p><strong>Speaking</strong> The frogs come back to this pond every spring — amphibians are weirdly loyal to one spot.</p><blockquote><p>每年春天青蛙都会回到这个池塘，两栖动物对一处地方黏得莫名其妙。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>frog</td><td>青蛙</td><td>具体一种，不能泛指整类</td></tr><tr><td>reptile</td><td>爬行动物</td><td>皮肤干燥有鳞，卵产在陆上</td></tr><tr><td>aquatic animal</td><td>水生动物</td><td>只强调生活在水中</td></tr><tr><td>vertebrate</td><td>脊椎动物</td><td>上位词，范围更大</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> amphi-（希腊语&quot;两边&quot;）+ bios（生命）→ 两种生活</li><li><strong>Family:</strong> amphibious 两栖的 / amphibious vehicle 水陆两用车 / amphitheatre 圆形剧场（两侧看台）</li><li><strong>Memory Tip:</strong> amphi- 是&quot;两边&quot;：两栖动物小时候在水里用鳃、长大在陆地用肺，一生过两种日子。同族的 amphitheatre 是&quot;两边都能坐的剧场&quot;，一个前缀打通。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写是 amphi-，不是 <s>amfi-</s>；重音在第二音节 /æmˈfɪbiən/。</li><li>形容词是 <strong>amphibian</strong>（定语）或 <strong>amphibious</strong>（水陆两用的），别混用：amphibious <strong>vehicle</strong> ✔</li><li>蛙类属于 amphibian，不属于 reptile。</li></ul></div><div class="vocab-card"><h2 id="carnivore" tabindex="-1"><a class="header-anchor" href="#carnivore"><span>Carnivore</span></a></h2><p class="vc-meta"><strong>/ˈkɑːnɪvɔː(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>食肉动物；肉食动物</li><li>爱吃肉的人（口语、戏谑）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a top carnivore</td><td>顶级食肉动物</td></tr><tr><td>large carnivores</td><td>大型食肉动物</td></tr><tr><td>carnivores and herbivores</td><td>食肉动物与食草动物</td></tr><tr><td>a carnivore&#39;s diet</td><td>食肉动物的食谱</td></tr><tr><td>apex carnivore</td><td>顶端捕食者</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how energy passes from plants to herbivores and then to carnivores.</p><blockquote><p>该示意图展示了能量如何从植物流向食草动物，再流向食肉动物。</p></blockquote><p><strong>Writing Task 2</strong> Removing the top carnivore from a food web rarely leaves things unchanged: herbivore numbers surge and vegetation is stripped bare.</p><blockquote><p>从食物网中移除顶级食肉动物很少不引发变化：食草动物数量激增，植被被啃食殆尽。</p></blockquote><p><strong>Speaking</strong> I&#39;m a total carnivore — my idea of a salad is chicken on top of more chicken.</p><blockquote><p>我是彻底的肉食动物，我理解的沙拉就是鸡肉上面再放鸡肉。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>predator</td><td>捕食者</td><td>强调捕食行为，不一定只吃肉</td></tr><tr><td>meat-eater</td><td>食肉者</td><td>口语，无学术色彩</td></tr><tr><td>hunter</td><td>猎手</td><td>强调主动捕猎，可指人</td></tr><tr><td>scavenger</td><td>食腐动物</td><td>吃死尸，不主动捕猎</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> carni-（拉丁 <em>caro</em>，肉）+ -vore（吃）</li><li><strong>Family:</strong> carnivorous 食肉的 / herbivore 食草动物 / omnivore 杂食动物 / voracious 贪婪的</li><li><strong>Memory Tip:</strong> -vore 是&quot;吃&quot;，前面换词根就换食谱：carni 肉、herbi 草、omni 全都吃。三个词排成一行，比单个背快三倍。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>形容词是 <strong>carnivorous</strong>：carnivorous <strong>plants</strong> ✔ / <s>carnivore plants</s> ✘</li><li>拼写是 carni-，不是 <s>carna-</s>；-vore 结尾不读 /-vɔː/ 而是 /-vɔː(r)/。</li><li>熊既吃鱼也吃果子，严格说是 omnivore，别一概称 carnivore。</li></ul></div><div class="vocab-card"><h2 id="herbivore" tabindex="-1"><a class="header-anchor" href="#herbivore"><span>Herbivore</span></a></h2><p class="vc-meta"><strong>/ˈhɜːbɪvɔː(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>食草动物；植食动物</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>large herbivores</td><td>大型食草动物</td></tr><tr><td>herbivores and carnivores</td><td>食草动物与食肉动物</td></tr><tr><td>a herbivore&#39;s teeth</td><td>食草动物的牙齿</td></tr><tr><td>grazing herbivores</td><td>放牧型食草动物</td></tr><tr><td>herbivore populations</td><td>食草动物种群</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph compares the biomass of herbivores and carnivores in the two ecosystems.</p><blockquote><p>该图比较了两个生态系统中食草动物与食肉动物的生物量。</p></blockquote><p><strong>Writing Task 2</strong> Without large herbivores to keep grass short, dry seasons turn grassland into a tinderbox.</p><blockquote><p>没有大型食草动物把草吃短，旱季就会把草原变成一点就着的火药桶。</p></blockquote><p><strong>Speaking</strong> Rabbits look harmless, but as herbivores they can strip a vegetable patch overnight.</p><blockquote><p>兔子看着无害，但作为食草动物，一夜之间就能把菜地啃光。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>plant-eater</td><td>食植者</td><td>口语说法，不够学术</td></tr><tr><td>grazer</td><td>食草者</td><td>专指吃地面牧草的，不含啃树叶的</td></tr><tr><td>browser</td><td>食叶动物</td><td>指吃灌木树叶的，与 grazer 相对</td></tr><tr><td>omnivore</td><td>杂食动物</td><td>什么都吃，与 herbivore 对立</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> herbi-（拉丁 <em>herba</em>，草）+ -vore（吃）</li><li><strong>Family:</strong> herb 草本植物 / herbal 草本的 / herbivorous 食草的 / herbicide 除草剂</li><li><strong>Memory Tip:</strong> herb 在超市里就是&quot;香草&quot;，herbivore 就是&quot;吃草的&quot;。同一词根的 herbicide 是&quot;杀草的&quot;——一个吃草，一个杀草，正好配对。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>形容词是 <strong>herbivorous</strong>：herbivorous <strong>dinosaurs</strong> ✔</li><li>注意 h 不发音的情况只出现在 herb（美式 /ɜːrb/），herbivore 的 h 要读 /h/。</li><li>牛、羊、马是 herbivore；猪、熊是 omnivore，别一律归为食草。</li></ul></div><div class="vocab-card"><h2 id="beast" tabindex="-1"><a class="header-anchor" href="#beast"><span>Beast</span></a></h2><p class="vc-meta"><strong>/biːst/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>（尤指大型、危险的）野兽、走兽</li><li>（贬义或戏谑）粗野的人；（某方面）极强的东西</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a wild beast</td><td>野兽</td></tr><tr><td>beast of burden</td><td>役畜</td></tr><tr><td>a beast of prey</td><td>猛兽</td></tr><tr><td>the beast in him</td><td>他内心的兽性</td></tr><tr><td>a different beast</td><td>完全不同的东西</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The illustration shows how a beast of burden was used to transport goods across the pass.</p><blockquote><p>该图示展示了役畜如何被用来把货物运过山口。</p></blockquote><p><strong>Writing Task 2</strong> Urban expansion pushes wild beasts into farmland, where a single night of raiding can wipe out a family&#39;s harvest.</p><blockquote><p>城市扩张把野兽逼进农田，一夜的抢食就能毁掉一家人一整季的收成。</p></blockquote><p><strong>Speaking</strong> The trail was steep and muddy — by the end I felt like a beast of burden myself.</p><blockquote><p>那条小路又陡又烂，走到最后我觉得自己就是头役畜。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>animal</td><td>动物</td><td>中性科学词，无威胁含义</td></tr><tr><td>creature</td><td>生物</td><td>语气温和，可指小动物</td></tr><tr><td>brute</td><td>畜生</td><td>强调粗暴、无理性，贬义更强</td></tr><tr><td>wildlife</td><td>野生动物</td><td>集合名词，不指单个个体</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>bestia</em>（野兽）</li><li><strong>Family:</strong> bestial 野兽般的 / bestiality 兽性 / beastly 恶劣的（英式口语）</li><li><strong>Memory Tip:</strong> beauty and the beast——&quot;美女与野兽&quot;。记住这个片名就记住了 beast 的&quot;大、凶、兽&quot;三重色彩，比背释义直观。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>beast 带情绪色彩，科技文本描述物种应改用 animal / species。</li><li>&quot;役畜&quot;固定说 <strong>beast of burden</strong>，不用 <s>beast for burden</s>。</li><li>口语 &quot;a different beast&quot; 意为&quot;另一回事&quot;，不是&quot;另一只野兽&quot;。</li></ul></div><div class="vocab-card"><h2 id="brute" tabindex="-1"><a class="header-anchor" href="#brute"><span>Brute</span></a></h2><p class="vc-meta"><strong>/bruːt/</strong> · noun · 名词 / adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>畜生；粗暴残忍的人</li><li>蛮力的、粗暴的（形容词，作定语）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a big brute</td><td>一个块头很大的粗暴家伙</td></tr><tr><td>brute force</td><td>蛮力</td></tr><tr><td>brute strength</td><td>蛮劲</td></tr><tr><td>a brute of a man</td><td>粗野的汉子</td></tr><tr><td>by brute force</td><td>靠蛮力</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart contrasts the brute strength of draft animals with the efficiency of modern machinery.</p><blockquote><p>该图对比了役畜的蛮力与现代机械的效率。</p></blockquote><p><strong>Writing Task 2</strong> Conservation cannot succeed by brute force alone; fencing off an area without local support usually fails within a decade.</p><blockquote><p>保护工作仅靠蛮力无法成功；没有当地支持就圈起一片区域，通常十年内就会失败。</p></blockquote><p><strong>Speaking</strong> He&#39;s a big brute, but he cries at dog commercials — which is honestly quite sweet.</p><blockquote><p>他块头大、看着凶，却会为狗狗广告流泪，说实话挺可爱的。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>beast</td><td>野兽</td><td>指动物或兽性，不一定指人</td></tr><tr><td>thug</td><td>暴徒</td><td>指使用暴力的罪犯</td></tr><tr><td>savage</td><td>野蛮人</td><td>强调未开化，冒犯性强</td></tr><tr><td>bully</td><td>欺凌者</td><td>指以强凌弱，未必动武</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>brutus</em>（沉重的、无理性的）→ 同源 <em>brute</em> 指&quot;没有理性的畜生&quot;</li><li><strong>Family:</strong> brutal 残忍的 / brutality 暴行 / brutish 粗野的 / brutalism 粗野主义（建筑）</li><li><strong>Memory Tip:</strong> brute 与 brutal 同根：一个&quot;蛮&quot;，一个&quot;残&quot;。著名典故 &quot;Et tu, Brute?&quot; 里的 Brute 是人名，但拼写一样，可以借来记形状。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>用于人时贬义很重，正式文本慎用；书面批评更常说 violent / aggressive。</li><li>形容词 <strong>brute</strong> 只作定语（brute force），作表语要用 <strong>brutal</strong>：He is <strong>brutal</strong>. ✔</li><li>拼写是 bru-，不是 <s>broo-</s>。</li></ul></div><div class="vocab-card"><h2 id="cruel" tabindex="-1"><a class="header-anchor" href="#cruel"><span>Cruel</span></a></h2><p class="vc-meta"><strong>/ˈkruːəl/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>残忍的，残酷的（对人、对动物）</li><li>令人痛苦的，严酷的（天气、命运、现实）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>be cruel to animals</td><td>虐待动物</td></tr><tr><td>cruel treatment</td><td>残忍的对待</td></tr><tr><td>a cruel twist of fate</td><td>命运的残酷转折</td></tr><tr><td>cruel and unusual punishment</td><td>残酷异常的刑罚</td></tr><tr><td>it is cruel to ...</td><td>……是残忍的</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the number of reported cases of cruel treatment of farm animals in five countries.</p><blockquote><p>该图显示了五个国家上报的农场动物虐待案件数量。</p></blockquote><p><strong>Writing Task 2</strong> Keeping a social animal alone in a small cage is not merely unkind but cruel, since it denies the animal every behaviour its instincts demand.</p><blockquote><p>把群居动物单独关在小笼子里不只是不友善，而是残忍，因为这剥夺了它本能要求的一切行为。</p></blockquote><p><strong>Speaking</strong> It&#39;s cruel to leave a dog in a car on a hot day — people still do it, though.</p><blockquote><p>大热天把狗留在车里很残忍，但依然有人这么干。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>brutal</td><td>残暴的</td><td>强调暴力与血腥，程度比 cruel 重</td></tr><tr><td>inhuman</td><td>无人性的</td><td>多用于制度、待遇，书面正式</td></tr><tr><td>harsh</td><td>严酷的</td><td>多指条件、措施，不含恶意</td></tr><tr><td>vicious</td><td>恶毒的</td><td>强调有意加害，带攻击性</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>crudelis</em>（冷酷的），与 <em>crudus</em>（生的、未熟的）同源</li><li><strong>Family:</strong> cruelty 残忍 / cruelly 残忍地 / crude 粗糙的、未加工的（同源）</li><li><strong>Memory Tip:</strong> 同源的 crude 是&quot;生的、粗的&quot;——cruel 就是&quot;心还是生的、没被教养煮熟的&quot;，所以下得去手。这个比喻把两个词一起钉住。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>介词固定用 <strong>to</strong>：cruel <strong>to</strong> animals ✔ / <s>cruel with animals</s> ✘</li><li>名词是 <strong>cruelty</strong>：animal <strong>cruelty</strong> ✔ / <s>animal cruel</s> ✘</li><li>拼写是 cru-el，两个音节，不是 <s>crul</s>。</li></ul></div><div class="vocab-card"><h2 id="flock" tabindex="-1"><a class="header-anchor" href="#flock"><span>Flock</span></a></h2><p class="vc-meta"><strong>/flɒk/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>（羊、鸟的）群；一群（同类人或物）</li><li>蜂拥、成群结队地去（动词）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a flock of sheep</td><td>一群羊</td></tr><tr><td>a flock of birds</td><td>一群鸟</td></tr><tr><td>in flocks</td><td>成群地</td></tr><tr><td>flock to the city</td><td>涌向城市</td></tr><tr><td>birds of a feather flock together</td><td>物以类聚</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows how the size of a migratory flock changed over the season.</p><blockquote><p>该图显示了一个迁徙鸟群的规模在整个季节中的变化。</p></blockquote><p><strong>Writing Task 2</strong> Every winter, tourists flock to the reserve, and the revenue they bring is what keeps the rangers employed.</p><blockquote><p>每年冬天游客涌向保护区，他们带来的收入正是护林员的工资来源。</p></blockquote><p><strong>Speaking</strong> A flock of pigeons took off all at once — the sound of all those wings was surprisingly loud.</p><blockquote><p>一群鸽子同时起飞，那么多翅膀的声音大得意外。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>herd</td><td>群</td><td>多用于牛、马、象等大型哺乳动物</td></tr><tr><td>pack</td><td>群</td><td>用于狼、狗等犬科，带&quot;群体狩猎&quot;义</td></tr><tr><td>swarm</td><td>群</td><td>用于蜂、蝗等密集小虫，数量感强</td></tr><tr><td>crowd</td><td>人群</td><td>只用于人</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>flocc</em>（一群、一簇）</li><li><strong>Family:</strong> flock 群 / flocking 聚集 / flight 飞行（不同源但常配记忆）</li><li><strong>Memory Tip:</strong> 按&quot;动物 + 量词&quot;配对记：sheep→flock、cattle→herd、wolves→pack、bees→swarm。四组一起背，写作时选词不会错。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>羊、鸟用 <strong>flock</strong>，牛马用 <strong>herd</strong>，不要说 <s>a flock of cows</s>。</li><li>动词用法常带方向：flock <strong>to</strong> the coast ✔ / <s>flock the coast</s> ✘</li><li>拼写 -ock，不是 <s>-ok</s>。</li></ul></div><div class="vocab-card"><h2 id="herd" tabindex="-1"><a class="header-anchor" href="#herd"><span>Herd</span></a></h2><p class="vc-meta"><strong>/hɜːd/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>兽群、畜群（尤指牛、马、象等大型动物）</li><li>放牧；把……赶在一起（动词）</li><li>人群（贬义，指盲从的大众）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a herd of cattle</td><td>一群牛</td></tr><tr><td>a herd of elephants</td><td>一群大象</td></tr><tr><td>herd behaviour</td><td>从众行为</td></tr><tr><td>herd immunity</td><td>群体免疫</td></tr><tr><td>herd animals into ...</td><td>把动物赶进……</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the size of elephant herds counted in the park each year.</p><blockquote><p>该图显示了每年在公园内统计到的大象群规模。</p></blockquote><p><strong>Writing Task 2</strong> Fencing water sources forces wild herds to concentrate in small areas, which accelerates the spread of disease.</p><blockquote><p>把水源围起来会迫使野生兽群集中在小片区域内，从而加速疾病传播。</p></blockquote><p><strong>Speaking</strong> The whole herd crossed the road at once, and we just sat there for ten minutes.</p><blockquote><p>整群动物一起过马路，我们就在那儿坐了十分钟。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>flock</td><td>群</td><td>多用于羊与鸟</td></tr><tr><td>pack</td><td>群</td><td>犬科动物，强调群体捕猎</td></tr><tr><td>drove</td><td>畜群</td><td>特指被驱赶的牛、猪群，古旧</td></tr><tr><td>crowd</td><td>人群</td><td>只用于人，含拥挤义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>heord</em>（群、看护）</li><li><strong>Family:</strong> herdsman 牧人 / herder 放牧者 / herd 放牧 / shepherd 牧羊人（近义）</li><li><strong>Memory Tip:</strong> herder 是&quot;放牧的人&quot;，herd 是&quot;被放的群&quot;——同一个词根，一个主动一个被动。看到 -er 就想到&quot;人&quot;，主客关系立刻分清。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>牛群用 herd，羊群用 flock；<s>a herd of sheep</s> 虽偶见但不地道。</li><li>&quot;从众心理&quot;固定说 <strong>herd mentality / herd behaviour</strong>，不用 <s>crowd mentality</s>。</li><li>动词 herd 是&quot;驱赶&quot;，不是&quot;放牧吃草&quot;（那是 graze）。</li></ul></div><div class="vocab-card"><h2 id="swarm" tabindex="-1"><a class="header-anchor" href="#swarm"><span>Swarm</span></a></h2><p class="vc-meta"><strong>/swɔːm/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>（蜂、蚁、蝗虫等的）一大群；密集的一群</li><li>蜂拥、成群移动；挤满（动词）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a swarm of bees</td><td>一群蜜蜂</td></tr><tr><td>a swarm of locusts</td><td>一群蝗虫</td></tr><tr><td>swarm around ...</td><td>围着……乱转</td></tr><tr><td>swarm into ...</td><td>涌入……</td></tr><tr><td>in swarms</td><td>成群地</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the areas affected as a locust swarm moved north across the region.</p><blockquote><p>该地图显示了蝗群向北穿过该地区时受影响的范围。</p></blockquote><p><strong>Writing Task 2</strong> When a swarm of locusts descends, a single afternoon can destroy what a village planned to eat for a year.</p><blockquote><p>蝗群一旦落下，一个下午就能毁掉一个村子打算吃一年的粮食。</p></blockquote><p><strong>Speaking</strong> Bees swarmed around the bin outside the café, and nobody wanted to be the one to throw anything away.</p><blockquote><p>蜜蜂在咖啡馆外的垃圾桶旁乱飞，没人愿意去扔垃圾。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>flock</td><td>群</td><td>多用于鸟与羊，密度感不如 swarm</td></tr><tr><td>crowd</td><td>人群</td><td>只用于人</td></tr><tr><td>horde</td><td>一大群</td><td>贬义，多指人或入侵者</td></tr><tr><td>cluster</td><td>簇</td><td>静态聚集，不强调移动</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>swearm</em>（蜂群）</li><li><strong>Family:</strong> swarming 成群移动的 / swarm 蜂群 / beehive 蜂巢（关联记忆）</li><li><strong>Memory Tip:</strong> swarm 天生带&quot;嗡嗡作响、密密麻麻&quot;的画面。写作里描述昆虫、人群涌入，用 swarm 比 a lot of 生动得多——这个词本身就是一个镜头。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>swarm 强调&quot;密集且移动&quot;，静态的一堆东西用 cluster / group。</li><li>动词常与 around / into 搭配，不能直接跟宾语表&quot;挤满某处&quot;以外的意思。</li><li>说&quot;一群蜜蜂&quot;用 a swarm of bees；蜂巢是 hive，不是 swarm。</li></ul></div><div class="vocab-card"><h2 id="throng" tabindex="-1"><a class="header-anchor" href="#throng"><span>Throng</span></a></h2><p class="vc-meta"><strong>/θrɒŋ/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>人群；密集的一群（书面语，多指人多拥挤）</li><li>蜂拥、挤满（动词，书面）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a throng of tourists</td><td>一群游客</td></tr><tr><td>throngs of visitors</td><td>大批游客</td></tr><tr><td>throng the streets</td><td>挤满街道</td></tr><tr><td>a cheering throng</td><td>欢呼的人群</td></tr><tr><td>throng into ...</td><td>涌入……</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows how many visitors thronged the national park in each month of 2023.</p><blockquote><p>该图显示了 2023 年各月涌入国家公园的游客数量。</p></blockquote><p><strong>Writing Task 2</strong> Each spring, throngs of visitors arrive to watch the cranes return, and the disturbance they cause is now a management problem.</p><blockquote><p>每年春天大批游客前来观看鹤群归来，他们造成的干扰如今已成了管理难题。</p></blockquote><p><strong>Speaking</strong> The night market was packed — a slow-moving throng of people and strollers and one very patient dog.</p><blockquote><p>夜市挤得水泄不通，缓慢移动的人流、婴儿车，还有一只特别有耐心的狗。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>crowd</td><td>人群</td><td>最通用，口语书面皆可</td></tr><tr><td>swarm</td><td>群</td><td>多用于昆虫，用于人有贬义</td></tr><tr><td>multitude</td><td>众多</td><td>抽象、书面，强调数量大</td></tr><tr><td>horde</td><td>一大群</td><td>贬义，常指入侵式的人流</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>thringan</em>（挤压）→ throng 即&quot;挤在一起的人&quot;</li><li><strong>Family:</strong> throng 人群 / thronged 挤满的 / thronging 蜂拥的</li><li><strong>Memory Tip:</strong> throng 与 &quot;thronging streets&quot; 这类搭配绑定，读起来就有一股挤压感。它是新闻与文学里的&quot;人多&quot;专用词，比 crowd 更书面。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>属书面语，口语里说 crowd 更自然。</li><li>作动词是及物用法：Tourists <strong>throng</strong> the beach. ✔ / <s>Tourists throng to the beach</s>（可接受但不如 crowd to 常见）</li><li>拼写 thr- 开头，别与 <s>through</s> 混。</li></ul></div><div class="vocab-card"><h2 id="crowd" tabindex="-1"><a class="header-anchor" href="#crowd"><span>Crowd</span></a></h2><p class="vc-meta"><strong>/kraʊd/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>人群；观众；（特定的）一群人</li><li>挤满、聚集；挤，推（动词）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a crowd of people</td><td>一群人</td></tr><tr><td>a capacity crowd</td><td>满座的观众</td></tr><tr><td>crowd into ...</td><td>涌入……</td></tr><tr><td>stand out from the crowd</td><td>脱颖而出</td></tr><tr><td>a crowd of tourists</td><td>一群游客</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows visitor numbers at the zoo, with a peak when a capacity crowd filled the park in July.</p><blockquote><p>该图显示了动物园的游客数量，7 月满员时达到高峰。</p></blockquote><p><strong>Writing Task 2</strong> Wherever a rare animal is publicised, crowds follow, and the pressure they put on a small habitat can be greater than that of any predator.</p><blockquote><p>稀有动物一经宣传，人群随之而至，他们对狭小栖息地造成的压力可能超过任何捕食者。</p></blockquote><p><strong>Speaking</strong> The crowd went completely silent when the elephant walked out — you could hear kids gasping.</p><blockquote><p>大象走出来时全场安静下来，能听见孩子们倒吸一口气。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>throng</td><td>人群</td><td>更书面，强调拥挤</td></tr><tr><td>audience</td><td>观众</td><td>指有观看关系的一群人</td></tr><tr><td>mob</td><td>暴民</td><td>贬义，暗示失控与暴力</td></tr><tr><td>gathering</td><td>集会</td><td>中性，规模较小、有目的</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>crūdan</em>（推挤）</li><li><strong>Family:</strong> crowded 拥挤的 / overcrowded 过度拥挤的 / crowd 挤满</li><li><strong>Memory Tip:</strong> crowd 的本义是&quot;推&quot;。想想早高峰地铁——不是&quot;有一堆人&quot;，而是&quot;人贴着人往前挤&quot;。用这个画面记 crowded 这个高频形容词。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>作动词表&quot;挤满某地&quot;是及物：Tourists <strong>crowded</strong> the square. ✔ / <s>Tourists crowded in the square</s>（意思变了）</li><li>可数名词，指整体时常用单数：The crowd <strong>was</strong> large. ✔（英式）</li><li>拼写 cr-，不是 <s>croud</s>。</li></ul></div>`,25)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};